#include <iostream>
#include <mutex>
#include <thread>

int counter = 0;
std::mutex m;                                 // protege a counter

void incrementar() {
    for (int i = 0; i < 100000; i++) {
        m.lock();                             // pide la llave (espera si otro la tiene)
        counter++;                            // sección crítica: un hilo a la vez
        m.unlock();                           // devuelve la llave
    }
}

int main() {
    std::thread t1(incrementar), t2(incrementar);
    t1.join();
    t2.join();
    std::cout << counter << '\n';             // siempre 200000
}

void incrementar() {
    for (int i = 0; i < 100000; i++) {
        std::lock_guard<std::mutex> guard(m);   // constructor: m.lock()
        counter++;
    }                                            // destructor de guard: m.unlock()
}

#include <mutex>
#include <string>

std::mutex m;
std::string ultimo_mensaje;                   // dato compartido

void procesar(const std::string& nuevo) {
    std::unique_lock<std::mutex> lk(m);       // toma m
    ultimo_mensaje = nuevo;                   // sección crítica corta
    lk.unlock();                              // suelta m ANTES de la parte lenta

    escribir_en_disco(nuevo);                 // no necesita el mutex: otros hilos avanzan
}                                             // destructor: no hace nada (ya no tiene m)

std::mutex a, b;

// ❌ DEADLOCK: cada hilo toma los mutex en orden distinto
void hilo1() { std::lock_guard<std::mutex> g1(a); std::lock_guard<std::mutex> g2(b); /*...*/ }
void hilo2() { std::lock_guard<std::mutex> g1(b); std::lock_guard<std::mutex> g2(a); /*...*/ }
// hilo1 toma a, hilo2 toma b → hilo1 espera b, hilo2 espera a → ciclo

// ✅ Solución 1: orden global. Todos toman a y luego b.
void hilo2_ok() { std::lock_guard<std::mutex> g1(a); std::lock_guard<std::mutex> g2(b); /*...*/ }

// ✅ Solución 2 (C++17): scoped_lock toma varios mutex sin deadlock,
// sin importar el orden en que los pases.
void hilo2_mejor() {
    std::scoped_lock lk(b, a);               // usa std::lock por dentro: todos o ninguno
    /*...*/
}                                            // suelta ambos al salir

